/**
 * D27 US-spelling pass, leftovers (2026-11-05). On-screen text says "program",
 * "theater", "license", "fiberglass". Code identifiers (useDrawProgramme,
 * programmeDb, 'musical-theatre', family ids) are NOT display text and stay.
 *
 * ⛔ careerIndex.json and careerFamilies.json are generated by
 * scripts/build-career-index.py; the shipped files are what these pin.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';

import { LOUDNESS_SCENARIOS } from '../src/screens/lab/mastering/masteringContent.ts';

const read = (p: string) => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8').replace(/\r\n/g, '\n');

describe('US spelling in on-screen text', () => {
  const pins: [file: string, gone: string, now: string][] = [
    ['src/data/credentialCopy.ts', 'hearing-conservation programme', 'hearing-conservation program '],
    ['src/screens/lab/mastering/masteringContent.ts', "why: 'Programme loudness", "why: 'Program loudness"],
    ['src/screens/lab/mastering/masteringContent.ts', 'loudness of the whole programme', 'loudness of the whole program '],
    ['src/screens/lab/mastering/modules/mod6Loudness.tsx', 'average of the whole programme', 'average of the whole program '],
    ['src/screens/lab/calc/workspaces/loudness.ts', 'real programme loudness', 'real program loudness'],
    ['src/features/startHere/startHereGlossary.ts', 'peak programme meter', 'peak program meter'],
    ['src/screens/lab/roomdesign/roomModel.ts', 'fibreglass', 'mineral wool or fiberglass with gloves'],
    ['src/data/careerIndex.json', 'licence', "an electrician's license"],
    ['src/data/careerIndex.json', 'contractor licence', 'contractor license'],
  ];
  for (const [file, gone, now] of pins) {
    it(`${file}: "${gone}" is gone`, () => {
      const s = read(file);
      assert.ok(!s.includes(gone), `still says: ${gone}`);
      assert.ok(s.includes(now), `missing: ${now}`);
    });
  }

  it('career family settings say theaters; the family id is untouched', () => {
    const s = read('src/data/careerFamilies.json');
    assert.ok(!s.includes('"theatres"'));
    assert.equal(s.split('"theaters"').length - 1, 3);
    assert.ok(s.includes('"id": "theatre-worship-venues-and-show-control"'));
  });

  it('quiz l2 is still answerable: `correct` is one of the options, in US spelling', () => {
    const q = LOUDNESS_SCENARIOS.find((x) => x.id === 'l2');
    assert.ok(q);
    assert.equal(q.correct, 'A gated, frequency-weighted average of the whole program');
    assert.ok(q.options.includes(q.correct));
  });
});
